import os
import csv
import re

def process_logs():
    base_dir = 'loglar'
    results = []

    if not os.path.exists(base_dir):
        print(f"Error: {base_dir} directory not found.")
        return

    for root, dirs, files in os.walk(base_dir):
        for file in files:
            # Sadece uzantısı tam olarak .log olan dosyalar
            if file.endswith('.log') and not file.endswith('.log.'):
                file_path = os.path.join(root, file)

                # Göreceli yolu oluştur ve ayırıcıyı / yap
                rel_path = os.path.relpath(file_path, base_dir).replace('\\', '/')

                error_count = 0
                warn_count = 0
                info_count = 0

                try:
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        for line in f:
                            parts = line.split()
                            # Format: TARİH SAAT SEVİYE mesaj
                            # En az 4 parça olmalı (Tarih, Saat, Seviye, Mesajın ilk kısmı)
                            if len(parts) >= 3:
                                level = parts[2]
                                if level == 'ERROR':
                                    error_count += 1
                                elif level == 'WARN':
                                    warn_count += 1
                                elif level == 'INFO':
                                    info_count += 1
                except Exception as e:
                    print(f"Could not read {file_path}: {e}")
                    continue

                results.append({
                    'dosya': rel_path,
                    'error': error_count,
                    'warn': warn_count,
                    'info': info_count
                })

    # Sıralama: error sayısına göre azalan, dosya yoluna göre artan
    # Python'un sort kararlı (stable) olduğu için önce yol, sonra error ile sıralayabiliriz
    # Veya tek bir key ile: (-error, dosya)
    results.sort(key=lambda x: (-x['error'], x['dosya']))

    output_file = 'rapor.csv'
    try:
        with open(output_file, 'w', newline='', encoding='utf-8') as csvfile:
            fieldnames = ['dosya', 'error', 'warn', 'info']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            writer.writeheader()
            for row in results:
                writer.writerow(row)
        print(f"Successfully created {output_file}")
    except Exception as e:
        print(f"Failed to write CSV: {e}")

if __name__ == "__main__":
    process_logs()

